/* ---------------- helpers ---------------- */
export function estimateReadingMinutes(post: BlogPost): number {
  if (post.readingMinutes) return post.readingMinutes;
  const words = post.content.reduce((n, b) => {
    if (b.type === "ul" || b.type === "ol") return n + b.items.join(" ").split(/\s+/).length;
    if ("text" in b) return n + b.text.split(/\s+/).length;
    return n;
  }, 0);
  return Math.max(1, Math.round(words / 200));
}

function byNewest(a: BlogPost, b: BlogPost) {
  return new Date(b.publishedOn).getTime() - new Date(a.publishedOn).getTime();
}

export function allPosts(): BlogPost[] {
  return [...posts].sort(byNewest);
}
export function getPost(slug: string): BlogPost | undefined {
  return posts.find((p) => p.slug === slug);
}
export function postsByCategory(category: string): BlogPost[] {
  return allPosts().filter((p) => p.category === category);
}
export function postsByTag(tag: string): BlogPost[] {
  return allPosts().filter((p) => p.tags.includes(tag));
}
export function postsByAuthor(author: string): BlogPost[] {
  return allPosts().filter((p) => p.author === author);
}
export function relatedPosts(post: BlogPost, limit = 3): BlogPost[] {
  const scored = allPosts()
    .filter((p) => p.slug !== post.slug)
    .map((p) => {
      let score = p.category === post.category ? 2 : 0;
      score += p.tags.filter((t) => post.tags.includes(t)).length;
      return { p, score };
    })
    .sort((a, b) => b.score - a.score || byNewest(a.p, b.p));
  return scored.slice(0, limit).map((s) => s.p);
}

// The first page is intentionally kept small (a focused "latest articles"
// preview on /blog itself); every page after that shows a much larger batch,
// since by then the reader is deliberately browsing the archive rather than
// skimming what's new.
export const POSTS_PER_PAGE_FIRST = 6;
export const POSTS_PER_PAGE = 24;

export function totalBlogPages(count: number): number {
  if (count <= POSTS_PER_PAGE_FIRST) return 1;
  return 1 + Math.ceil((count - POSTS_PER_PAGE_FIRST) / POSTS_PER_PAGE);
}

export function paginate(list: BlogPost[], page: number) {
  const total = totalBlogPages(list.length);
  const current = Math.min(Math.max(1, page), total);
  if (current <= 1) {
    return { items: list.slice(0, POSTS_PER_PAGE_FIRST), current, total };
  }
  const start = POSTS_PER_PAGE_FIRST + (current - 2) * POSTS_PER_PAGE;
  return { items: list.slice(start, start + POSTS_PER_PAGE), current, total };
}

/* ---------------- Table of Contents ---------------- */
export function headingSlug(text: string): string {
  return text.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}
export function tableOfContents(post: BlogPost): { id: string; text: string; level: 2 | 3 }[] {
  return post.content
    .filter((b): b is { type: "h2" | "h3"; text: string } => b.type === "h2" || b.type === "h3")
    .map((b) => ({ id: headingSlug(b.text), text: b.text, level: b.type === "h2" ? 2 : 3 }));
}
